"""Peak weighted pounds. Rate lookups are billed, so the peak is remembered."""
import rates


class DonationTracker:
    def __init__(self):
        self._donations = []
        self._peak = None

    def record(self, donation):
        """Record one donation."""
        self._donations.append(donation)

    def peak(self):
        """Return the highest pounds times rate seen so far, or 0 when nothing is recorded.

        The result is remembered: asking again without recording anything makes no new rate lookups.
        """
        if self._peak is None:
            self._peak = max((x.pounds * rates.rate_for(x.donor) for x in self._donations), default=0)
        return self._peak
